import{_ as r,l as n,o as e,c as d,v as t,p as l,x as o,d as s,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"指令选择","description":"","frontmatter":{"title":"指令选择","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/instruction-select.md","filePath":"cs/instruction-select.md","lastUpdated":1789023840000}'),p={name:"cs/instruction-select.md"};function A(_,a,u,I,m,f){const i=n("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="指令选择" tabindex="-1">指令选择 <a class="header-anchor" href="#指令选择" aria-label="Permalink to &quot;指令选择&quot;">​</a></h1><div class="epigraph"><p>把 IR 运算树（或 DAG）盖上目标机的指令模板；同一树可以有多种覆盖，代价不同。</p><footer>—— 据龙书第 8 章；Aho, Ganapathi and Tjiang, Code Generation Using Tree Matching, 1989 整理</footer></div><p>上一课<a href="/cs/available-expr">可用表达式</a>仍在虚拟名上。本课不着色。缺口是：三地址的 <code>+</code>、<code>load</code> 要变成<a href="/cs/riscv-int-isa">RISC-V 整数指令</a>或另一 ISA 的具体 opcode。选择可以局部树匹配，也可以 tiling。寄存器还当无限，名字仍是虚拟的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IR 是目标无关的。<code>t3 &lt;- t1 + t2</code> 在 RISC-V 是 <code>add</code>，在 CISC 可能是带访存的一条。缺口是模板：树模式 \\(\\leftrightarrow\\) 指令 + 代价。最大吞或动态规划选最小代价覆盖。本课用树模式直觉，不写完整 BURG 生成器。</p><p>组成课已有指令格式与寄存器堆；本课只问「哪条指令实现这个 IR 节点」。调用序列的参数寄存器留给 ABI。</p><h3 id="选择不是分配" tabindex="-1">选择不是分配 <a class="header-anchor" href="#选择不是分配" aria-label="Permalink to &quot;选择不是分配&quot;">​</a></h3><p>选出 <code>add rd, rs1, rs2</code> 仍带虚拟寄存器。分配把虚拟映到 <code>x10</code> 或溢出。顺序通常先选后分配，或二者交错；主干先选。窥孔还可以在选完后改写。</p><p><span class="marginnote">龙书 8.9 节树重写。Aho–Ganapathi–Tjiang 的树匹配。RISC 上选择往往接近 1:1，CISC 上 tiling 收益大。本课两边都承认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把基本块内 IR 看成森林/DAG。对每个根，用动态规划或贪婪匹配盖模板。访存指令带宽度，来自类型课的 size。非法组合（未对齐）按 ABI 与 ISA 拒绝或拆成多条。</p>',11)),(e(),l(h,null,{default:o(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22IR%20%E6%A0%91%20%2F%20DAG%22%5D%20--%3E%20PAT%5B%22ISA%20%E6%A8%A1%E6%9D%BF%22%5D%0A%20%20PAT%20--%3E%20TILE%5B%22%E8%A6%86%E7%9B%96%22%5D%0A%20%20TILE%20--%3E%20MI%5B%22%E6%9C%BA%E5%99%A8%E6%8C%87%E4%BB%A4%20%2B%20%E8%99%9A%E6%8B%9F%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><a href="/cs/instruction-format">指令格式</a>决定立即数能否塞进一条；放不下则先 <code>lui</code>/<code>addi</code> 一类，仍是选择。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代价：周期或长度。错误选择会多指令，不一定错语义。副作用（标志位）在 CISC 上要进模板。RISC-V 整数子集本课够用；浮点、向量不在本课。</p><p>与超标量、流水线课：选择可以避开已知冒险对，但不代替分配与调度。本课不排流水线调度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不填着色、不写调用惯例细节、不做全局指令调度。窥孔是更窄窗口的本地改写，后两课才到。后课默认：虚拟寄存器机器指令已选出。冲突图着色把虚拟收成物理寄存器或溢出。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指令选择 = ISA 模板覆盖 IR；代价可选优。</li><li>输出仍含虚拟寄存器。</li><li>RISC 近 1:1；复杂 ISA 才显 tiling。</li><li>出处：Aho et al., 龙书第 8 章；Aho, Ganapathi and Tjiang, 1989。</li></ul>',8))])}const E=r(p,[["render",A]]);export{T as __pageData,E as default};
